const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".app{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:6px;padding:10px;min-width:0;min-height:0;overflow:hidden;color:var(--ink);font:12px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;font-variant-numeric:tabular-nums}\n.app *{box-sizing:border-box}\n.mut{color:var(--muted)}\n.hd{display:flex;align-items:center;justify-content:space-between;gap:8px;flex:none;min-width:0}\n.ttl{font-size:13px;font-weight:700;letter-spacing:.04em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}\n\n.btn{font:inherit;font-size:12px;font-weight:600;height:28px;padding:0 11px;border-radius:8px;border:1px solid var(--line);background:var(--button-paper,var(--paper));color:var(--ink);cursor:pointer;white-space:nowrap;display:inline-flex;align-items:center;justify-content:center;gap:4px;flex:none}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.btn.ghost{background:transparent}\n.btn.sm{height:26px;padding:0 10px;font-size:11px}\n.btn.xs{height:22px;padding:0 8px;font-size:11px;border-radius:6px}\n.btn:disabled{opacity:.55;cursor:default}\n.btn:focus-visible,.tab:focus-visible,.rrow:focus-visible,.in:focus-visible,.sel:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.tabs{display:flex;gap:2px;padding:2px;border-radius:9px;background:var(--soft);flex:none}\n.tab{flex:1;min-width:0;height:22px;border:0;border-radius:7px;background:transparent;color:var(--muted);font:inherit;font-size:11px;font-weight:600;cursor:pointer;white-space:nowrap;padding:0 4px}\n.tab.on{background:var(--panel-paper);color:var(--ink);box-shadow:0 0 0 1px var(--line)}\n\n.pane{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column}\n.pane>.parts,.pane>.rlist,.pane>.empty-in{flex:none}\n.pane.col{gap:4px;overflow:hidden}\n.body{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:8px}\n.tabbody{flex:none}\n\n.sum{display:flex;flex-direction:column;gap:2px;min-width:0;flex:none}\n.sum-l{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sum-t{display:flex;align-items:baseline;flex-wrap:wrap;gap:2px 5px}\n.big{font-size:36px;line-height:1.05;font-weight:800;letter-spacing:-.02em}\n.unit{font-size:12px;color:var(--muted)}\n.sum-g{font-size:12px;font-weight:600}\n.sum-d{font-size:11px;color:var(--muted)}\n.dchip{display:inline-block;padding:1px 7px;border-radius:999px;font-size:11px;font-weight:700;white-space:nowrap;border:1px solid var(--line);background:var(--soft);color:var(--ink)}\n.dchip.up{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n\n.trend{display:flex;flex-direction:column;gap:4px;flex:1;min-width:0;min-height:0}\n.ctrl{display:flex;gap:6px;align-items:center;flex:none;min-width:0}\n.ctrl .sel{flex:1 1 0}\n.chartbox{position:relative;flex:1;min-height:30px;min-width:0}\n.chart{position:absolute;inset:0;width:100%;height:100%;display:block;overflow:visible}\n.cgrid{stroke:var(--line);stroke-width:1}\n.cline{fill:none;stroke:var(--accent);stroke-width:2;stroke-linejoin:round;stroke-linecap:round}\n.carea{fill:var(--accent);opacity:.12}\n.ctarget{fill:none;stroke:var(--accent-alt);stroke-width:1.5;stroke-dasharray:4 3}\n.cdot{fill:var(--panel-paper);stroke:var(--accent);stroke-width:2;cursor:pointer}\n.cdot.last{fill:var(--accent)}\n.clab{fill:var(--ink);font-size:10px;font-weight:700;text-anchor:middle}\n.cdate{fill:var(--muted);font-size:9px;text-anchor:middle}\n.note{color:var(--muted);font-size:11px;padding:8px 0}\n.legend{display:flex;flex-wrap:wrap;gap:2px 10px;font-size:10px;color:var(--muted);flex:none;min-width:0}\n.lg{display:inline-flex;align-items:center;gap:4px;min-width:0}\n.sw{display:inline-block;width:14px;height:0;border-top:2px solid var(--accent)}\n.sw.dash{border-top:2px dashed var(--accent-alt)}\n\n.sel{height:26px;min-width:0;max-width:100%;border:1px solid var(--line);border-radius:7px;background:var(--paper);color:var(--ink);font:inherit;font-size:11px;padding:0 4px}\n.in{width:100%;height:28px;min-width:0;border:1px solid var(--line);border-radius:7px;background:var(--paper);color:var(--ink);font:inherit;font-size:12px;padding:0 8px}\n\n.plist{display:flex;flex-direction:column;gap:8px}\n.prow{display:flex;flex-direction:column;gap:3px;min-width:0}\n.prow.none{opacity:.7}\n.prow-h{display:flex;align-items:baseline;gap:5px;min-width:0}\n.pn{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0;flex:0 1 auto}\n.ptag{flex:none;font-size:9px;font-weight:700;padding:0 4px;border-radius:4px;border:1px solid var(--accent);color:var(--ink);line-height:14px}\n.pv{margin-left:auto;flex:none;white-space:nowrap;font-weight:700;display:inline-flex;align-items:baseline;gap:5px}\n.pd{font-size:10px;font-weight:700;color:var(--muted)}\n.pd.up{color:var(--ink)}\n.pbar{position:relative;height:8px;border-radius:4px;background:var(--soft)}\n.fill{position:absolute;left:0;top:0;bottom:0;width:0;border-radius:4px;background:var(--accent)}\n.pmark{position:absolute;top:-3px;bottom:-3px;width:2px;margin-left:-1px;background:var(--ink);border-radius:1px}\n.hint{font-size:10px;color:var(--muted);line-height:1.45}\n.parts{display:flex;flex-direction:column;gap:8px;min-width:0}\n.empty-in{display:flex;flex-direction:column;gap:8px;align-items:flex-start;color:var(--muted);font-size:11px;padding:6px 0}\n.empty-in p{margin:0}\n\n.rlist{display:flex;flex-direction:column}\n.rrow{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;padding:6px 6px;border:0;border-bottom:1px solid var(--line);background:transparent;color:inherit;font:inherit;text-align:left;cursor:pointer;border-radius:6px;min-width:0}\n.rl,.rr{display:flex;flex-direction:column;min-width:0}\n.rr{align-items:flex-end;flex:none}\n.rd{font-weight:600;white-space:nowrap}\n.rt{font-size:17px;line-height:1.15;white-space:nowrap}\n.rs{font-size:10px;color:var(--muted);white-space:nowrap}\n\n\n/* empty state */\n.emptybox{flex:1;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;text-align:center;overflow:auto}\n.e-h{font-size:15px;font-weight:700}\n.e-p{font-size:11px;color:var(--muted);max-width:30em;line-height:1.5}\n\n/* panel views: form / detail / sections */\n.pv{gap:8px}\n.pv-hd{display:flex;align-items:center;gap:8px;flex:none;min-width:0}\n.pv-t{font-size:13px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}\n.pv-body{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:10px;padding-right:2px}\n.pv-ft{display:flex;flex-wrap:wrap;justify-content:flex-end;align-items:center;gap:6px;flex:none}\n.err{flex:1 1 100%;font-weight:700;font-size:11px;line-height:1.4}\n.pv-ft .err:only-child{flex:1 1 auto}\n.fgrid{display:grid;grid-template-columns:minmax(0,1fr);gap:8px}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.fl{font-size:11px;color:var(--muted);display:flex;align-items:center;justify-content:space-between;gap:6px}\n.sgroup{display:flex;flex-direction:column;gap:8px;align-items:flex-start}\n.sgroup .fgrid{width:100%}\n.sech{display:flex;align-items:center;justify-content:space-between;gap:6px;width:100%;font-size:12px;font-weight:700}\n.srows{display:flex;flex-direction:column;gap:6px;width:100%}\n.srow{display:flex;align-items:center;gap:5px;min-width:0}\n.srow .sname{flex:1 1 0}\n.srow .sfull{flex:none;width:58px}\n.stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}\n.stat{background:var(--soft);border-radius:8px;padding:6px 8px;min-width:0}\n.stl{font-size:10px;color:var(--muted)}\n.stat b{font-size:16px;white-space:nowrap}\n.notebox{font-size:11px;color:var(--muted);border-left:3px solid var(--line);padding:2px 8px;overflow-wrap:anywhere}\n\n/* size: 3x3 */\n.z3x3{padding:9px;gap:5px}\n.z3x3 .big{font-size:30px}\n.z3x3 .legend{display:none}\n.z3x3 .trend{gap:0}\n.z3x3 .hd .btn{height:24px;padding:0 8px}\n.z3x3 .emptybox{gap:6px}\n.z3x3 .e-h{font-size:13px}\n.z3x3 .e-p{font-size:10px}\n.z3x3 .stats{grid-template-columns:repeat(2,minmax(0,1fr))}\n\n/* size: 6x3 */\n.z6x3{flex-direction:row;gap:10px}\n.z6x3 .lcol{flex:none;width:128px;display:flex;flex-direction:column;gap:6px;min-width:0;justify-content:space-between}\n.z6x3 .rcol{flex:1;min-width:0;display:flex;flex-direction:column;gap:6px}\n.z6x3 .big{font-size:34px}\n.z6x3 .sum-g{font-size:11px}\n.z6x3 .fgrid{grid-template-columns:repeat(2,minmax(0,1fr))}\n.z6x3 .stats{grid-template-columns:repeat(4,minmax(0,1fr))}\n.z6x3.pv,.z6x3.empty{flex-direction:column}\n.z6x3.empty .emptybox{gap:6px}\n\n/* size: 3x6 */\n.z3x6 .chartbox{flex:none;height:112px}\n.z3x6 .trend{flex:none}\n\n/* size: 6x6 */\n.z6x6 .toprow{display:flex;gap:12px;flex:none;height:150px;min-height:0}\n.z6x6 .toprow .sum{width:128px;flex:none}\n.z6x6 .toprow .trend{flex:1;min-width:0}\n.z6x6 .fgrid{grid-template-columns:repeat(2,minmax(0,1fr))}\n.z6x6 .stats{grid-template-columns:repeat(4,minmax(0,1fr))}\n.z6x6 .rrow{padding:8px 8px}\n\n@media (prefers-reduced-motion:no-preference){\n  .btn,.tab{transition:background-color .12s,opacity .12s}\n}\n";
function toNum(v){
  if(v===null||v===undefined) return null;
  const t=String(v).trim();
  if(t==='') return null;
  const n=Number(t);
  return Number.isFinite(n)?n:NaN;
}
function fmt(n){
  if(typeof n!=='number'||!Number.isFinite(n)) return '—';
  return String(Math.round(n*100)/100);
}
function inStr(n){ return typeof n==='number'&&Number.isFinite(n)?String(n):''; }
function dparts(d){
  const p=String(d||'').split('-');
  return {y:p[0]||'',m:parseInt(p[1],10)||0,d:parseInt(p[2],10)||0};
}
function shortDate(d){ const p=dparts(d); return p.m?p.m+'/'+p.d:String(d||''); }
function longDate(d,yr){
  const p=dparts(d);
  if(!p.m) return String(d||'');
  return (p.y&&p.y!==yr?p.y+'年':'')+p.m+'月'+p.d+'日';
}
function normState(s){
  const o=s||{};
  const sections=(Array.isArray(o.sections)?o.sections:[]).filter(x=>x&&x.id);
  const records=(Array.isArray(o.records)?o.records:[]).filter(x=>x&&x.id&&typeof x.total==='number');
  const sorted=records.slice().sort((a,b)=>a.date<b.date?-1:a.date>b.date?1:0);
  return {sections,records,sorted};
}
function recScore(r,key){
  if(key==='total') return Number.isFinite(r.total)?r.total:null;
  const v=r.scores?r.scores[key]:undefined;
  return typeof v==='number'&&Number.isFinite(v)?v:null;
}
function gapInfo(r){
  if(!r||!Number.isFinite(r.target)||!Number.isFinite(r.total)) return {kind:'none'};
  const d=r.total-r.target;
  return d>=0?{kind:'met',diff:d}:{kind:'below',diff:-d};
}
function gapText(g){
  if(g.kind==='met') return g.diff===0?'刚好达标':'超出 '+fmt(g.diff)+' 分';
  if(g.kind==='below') return '还差 '+fmt(g.diff)+' 分';
  return '';
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,size}=ctx;
  const S=normState(state);
  const yr=day().slice(0,4);
  const z=size||'6x6';
  const wide=z==='6x3'||z==='6x6';
  const last=S.sorted.length?S.sorted[S.sorted.length-1]:null;
  if(!ui.view) ui.view='main';
  const h=(tag,attrs,...kids)=>el(tag,attrs||{},...kids.flat().filter(k=>k!==null&&k!==undefined&&k!==false));
  const prevOf=(rec)=>{const i=S.sorted.indexOf(rec);return i>0?S.sorted[i-1]:null;};
  const btn=(label,onclick,cls,attrs)=>h('button',Object.assign({type:'button',class:'btn '+(cls||''),onclick},attrs||{}),label);
  const mkSel=(opts,val,onch,label)=>{
    const s=h('select',{class:'sel','aria-label':label||'选择',onchange:(e)=>onch(e.target.value)},opts.map(o=>h('option',{value:String(o[0])},o[1])));
    s.value=String(val);
    return s;
  };
  function chip(d,withLabel){
    if(d===null) return null;
    const pre=withLabel?'较上次 ':'';
    if(d===0) return h('span',{class:'dchip eq'},pre+'持平');
    return h('span',{class:'dchip '+(d>0?'up':'dn')},pre+(d>0?'▲ ':'▼ ')+fmt(Math.abs(d)));
  }
  function openDetail(id){ui.id=id;ui.confirmDel=false;ui.err='';ui.view='detail';redraw();}

  function summary(rec,prev,compact){
    const g=gapInfo(rec);
    const d=prev?rec.total-prev.total:null;
    return h('div',{class:'sum'},
      h('div',{class:'sum-l'},'最近一次 · '+longDate(rec.date,yr)),
      h('div',{class:'sum-t'},h('b',{class:'big'},fmt(rec.total)),h('span',{class:'unit'},'分'),compact?chip(d,true):null),
      g.kind==='none'
        ?h('div',{class:'sum-g mut'},'未设目标分')
        :h('div',{class:'sum-g'},(g.kind==='met'?'✓ ':'')+'目标 '+fmt(rec.target)+' · '+gapText(g)),
      compact
        ?(d===null?h('div',{class:'sum-d mut'},'首次记录'):null)
        :(d===null?h('div',{class:'sum-d mut'},'首次记录，再记一次即可看到变化'):h('div',{class:'sum-d'},'较上次 ',chip(d,false))));
  }

  function chartSvg(pts,targets,W,H,compact,label){
    const n=pts.length;
    const m={l:16,r:16,t:compact?14:18,b:compact?4:19};
    const iw=W-m.l-m.r, ih=H-m.t-m.b;
    const vals=pts.map(p=>p.v).concat(targets.filter(t=>t!==null));
    let lo=Math.min(...vals), hi=Math.max(...vals);
    if(hi===lo){lo-=5;hi+=5;}else{const pad=(hi-lo)*0.2;lo-=pad;hi+=pad;}
    const X=i=>n===1?m.l+iw/2:m.l+iw*i/(n-1);
    const Y=v=>m.t+ih*(1-(v-lo)/(hi-lo));
    const r=x=>String(Math.round(x*10)/10);
    const k=[];
    [0,0.5,1].forEach(f=>k.push(h('line',{class:'cgrid',x1:r(m.l),x2:r(W-m.r),y1:r(m.t+ih*f),y2:r(m.t+ih*f)})));
    const tv=targets.filter(t=>t!==null);
    if(tv.length){
      if(tv.every(t=>t===tv[0])){
        k.push(h('line',{class:'ctarget',x1:r(m.l),x2:r(W-m.r),y1:r(Y(tv[0])),y2:r(Y(tv[0]))}));
      }else{
        const tp=[];
        targets.forEach((t,i)=>{if(t!==null)tp.push(r(X(i))+','+r(Y(t)));});
        k.push(h('polyline',{class:'ctarget',points:tp.join(' ')}));
      }
    }
    const lp=pts.map((p,i)=>r(X(i))+','+r(Y(p.v))).join(' ');
    if(n>1){
      k.push(h('polygon',{class:'carea',points:r(X(0))+','+r(m.t+ih)+' '+lp+' '+r(X(n-1))+','+r(m.t+ih)}));
      k.push(h('polyline',{class:'cline',points:lp}));
    }
    const showAt=(i,gap)=>{
      const step=Math.max(1,Math.ceil(n/Math.max(1,Math.floor(iw/gap))));
      return (n-1-i)%step===0;
    };
    pts.forEach((p,i)=>{
      const isLast=i===n-1;
      k.push(h('circle',{class:'cdot'+(isLast?' last':''),cx:r(X(i)),cy:r(Y(p.v)),r:isLast?'4.5':'3.2',onclick:()=>openDetail(p.rec.id)}));
      if(isLast||(!compact&&showAt(i,32))) k.push(h('text',{class:'clab',x:r(X(i)),y:r(Y(p.v)-8)},fmt(p.v)));
      if(!compact&&showAt(i,36)) k.push(h('text',{class:'cdate',x:r(X(i)),y:r(H-5)},shortDate(p.rec.date)));
    });
    return h('svg',{class:'chart',viewBox:'0 0 '+W+' '+H,role:'img','aria-label':label,preserveAspectRatio:'xMidYMid meet'},...k);
  }

  function trendBlock(){
    const compact=z==='3x3';
    const key=(ui.series&&S.sections.some(s=>s.id===ui.series))?ui.series:'total';
    const sec=key==='total'?null:S.sections.find(s=>s.id===key);
    const name=sec?(sec.name||'未命名'):'总分';
    const pts=[];
    S.sorted.forEach(rc=>{const v=recScore(rc,key);if(v!==null)pts.push({rec:rc,v});});
    const range=compact?5:(typeof ui.range==='number'?ui.range:5);
    const shown=range>0?pts.slice(-range):pts;
    const targets=key==='total'?shown.map(p=>Number.isFinite(p.rec.target)?p.rec.target:null):shown.map(()=>null);
    const dims={'3x3':[174,46],'6x3':[250,92],'3x6':[174,112],'6x6':[248,104]}[z]||[248,104];
    const ctrl=compact?null:h('div',{class:'ctrl'},
      mkSel([['total','总分']].concat(S.sections.map(s=>[s.id,s.name||'未命名'])),key,v=>{ui.series=v;redraw();},'选择走势对象'),
      mkSel([[5,'最近 5 次'],[10,'最近 10 次'],[0,'全部']],range,v=>{ui.range=Number(v);redraw();},'选择次数'));
    const tvals=targets.filter(t=>t!==null);
    const tl=!tvals.length?null:(tvals.every(t=>t===tvals[0])?'目标 '+fmt(tvals[0]):'目标（随记录）');
    return h('div',{class:'trend'},
      ctrl,
      h('div',{class:'chartbox'},shown.length
        ?chartSvg(shown,targets,dims[0],dims[1],compact,name+'最近'+shown.length+'次走势')
        :h('div',{class:'note'},'该分项还没有成绩')),
      h('div',{class:'legend'},
        h('span',{class:'lg'},h('i',{class:'sw'}),name),
        tl?h('span',{class:'lg'},h('i',{class:'sw dash'}),tl):null,
        shown.length===1?h('span',{class:'lg mut'},'目前只有 1 次成绩，再记一次即可看到变化'):null));
  }


  function partsList(rec,prev){
    const rows=S.sections.map(s=>({s,v:recScore(rec,s.id),p:prev?recScore(prev,s.id):null}));
    const have=rows.filter(x=>x.v!==null);
    const allFull=have.length>=2&&have.every(x=>Number.isFinite(x.s.full)&&x.s.full>0);
    let strong=null,weak=null;
    if(allFull){
      const rt=x=>x.v/x.s.full;
      strong=have.reduce((a,b)=>rt(b)>rt(a)?b:a);
      weak=have.reduce((a,b)=>rt(b)<rt(a)?b:a);
      if(rt(strong)-rt(weak)<1e-9){strong=null;weak=null;}
    }
    const mx=Math.max(1,...have.map(x=>Math.max(x.v,x.p===null?0:x.p)));
    const list=h('div',{class:'plist'});
    rows.forEach(x=>{
      const hasFull=Number.isFinite(x.s.full)&&x.s.full>0;
      const base=hasFull?x.s.full:mx;
      const fill=h('i',{class:'fill'});
      const bar=h('div',{class:'pbar'},fill);
      if(x.v!==null) fill.style.width=Math.min(100,Math.max(0,x.v/base*100))+'%';
      if(x.v!==null&&x.p!==null){
        const mk=h('i',{class:'pmark'});
        mk.style.left=Math.min(100,Math.max(0,x.p/base*100))+'%';
        bar.appendChild(mk);
      }
      const d=(x.v!==null&&x.p!==null)?x.v-x.p:null;
      const rate=(x.v!==null&&hasFull&&wide)?' · '+Math.round(x.v/x.s.full*100)+'%':'';
      list.appendChild(h('div',{class:'prow'+(x.v===null?' none':'')},
        h('div',{class:'prow-h'},
          h('span',{class:'pn'},x.s.name||'未命名'),
